  ok(r.red.length === 0, `§113 every hub-booting file is re-homed and every boot site's HOME comes from the re-homed process or a scratch source (${HUB_SITE_ROWS.length} named sites)${r.red.length ? ' — ' + r.red.join(' | ') : ''}`, r.red);
